/* The colour arrives as an inline custom property. Declared here with the
   system's own brand as its fallback, so the stylesheet is complete on its own
   and a swatch with no value is still a control rather than a hole. */
.color-swatch {
  --color-swatch: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  border: 1px solid var(--border);
  border-radius: var(--control-radius);
  background: var(--card);
  color: var(--foreground);
  font: inherit;
  cursor: pointer;
}

.color-swatch[data-size='md'] { padding: var(--space-2) var(--space-3); font-size: var(--font-sm); }
.color-swatch[data-size='sm'] { padding: var(--space-1) var(--space-2); font-size: var(--font-xs); }

/* The dot carries the colour and its own edge. The edge is what makes a white
   swatch on a white card a target rather than a gap. */
.color-swatch-dot {
  flex: 0 0 auto;
  inline-size: var(--space-4);
  block-size: var(--space-4);
  border-radius: var(--radius-full);
  background: var(--color-swatch);
  box-shadow: inset 0 0 0 1px var(--border);
}
.color-swatch[data-size='sm'] .color-swatch-dot { inline-size: var(--space-3); block-size: var(--space-3); }

/* Chosen is stated by the system's own emphasis, not by the swatch's colour:
   a selected state drawn in the value would be invisible for pale values and
   shouting for saturated ones. */
.color-swatch[data-selected] {
  border-color: var(--primary);
  box-shadow: inset 0 0 0 1px var(--primary);
}

/* Hover and press are the surface stepping, not the colour: the dot is data and
   must read the same whether or not a pointer is on it. One stop further on
   press, so a slow choice is not a dead control. */
.color-swatch:hover:not(:disabled) { background: var(--accent); }
.color-swatch:active:not(:disabled) { background: var(--accent-strong); }

.color-swatch:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}

.color-swatch:disabled {
  /* The same disabled treatment <Button> uses, so a dead control looks dead
     the one way in this system. */
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

import './ColorSwatch.css'
import type { CSSProperties } from 'react'
import { cn } from '../lib/cn'

/** How big the control is. `sm` sits in a dense panel; `md` in a form. */
type Size = 'sm' | 'md'

type Props = {
  /** The colour itself — any CSS colour. It is a VALUE, not a theme token. */
  value: string
  /**
   * What this colour is called. Required, and deliberately: a colour has no
   * accessible name of its own, so a swatch without one is a button that reads
   * as "button" to anyone not looking at it.
   */
  label: string
  /** Whether this is the chosen one. */
  selected?: boolean
  /** Called with the value when it is picked. */
  onSelect?: (value: string) => void
  /** How the set is used: `md` when picking is the task, `sm` for a row read as a summary of
   *  what is already chosen.
   */
  size?: Size
  /** For a colour that exists but cannot be chosen here — out of the plan, out of stock.
   *  Removing it instead would leave the reader wondering where it went.
   */
  disabled?: boolean
  className?: string
}

/**
 * A colour as a control: the value, its name, and a pressed state. Reach for it
 * anywhere a person picks a colour from a set someone curated — a brand, a
 * label, a calendar. For a free choice of any colour at all, this is the wrong
 * part; that is a picker, and the system does not have one.
 *
 * `<input type="color">` is the alternative it replaces, and it is the raw
 * control the linter refuses everywhere else: it cannot be styled, and it hands
 * the person an OS dialog that owes this system nothing.
 *
 * The dot draws its own edge from `--border` rather than from the colour, so a
 * swatch the colour of the surface it sits on is still a visible target — the
 * case a colour-as-background approach gets wrong exactly when it matters, on
 * white and on near-white.
 *
 * Copy: `label` is the colour's NAME in the reader's words — "Indigo", not
 * "#4638d3". A hex code is the value, and it is already the value.
 */
export function ColorSwatch({
  value,
  label,
  selected,
  onSelect,
  size = 'md',
  disabled,
  className,
}: Props) {
  return (
    <button
      type="button"
      className={cn('color-swatch', className)}
      data-size={size}
      data-selected={selected || undefined}
      /* A genuinely dynamic value, which is the one case inline style is for:
         it is data, and it cannot be a token because it is not a decision the
         system made. */
      style={{ '--color-swatch': value } as CSSProperties}
      aria-pressed={selected ?? false}
      disabled={disabled}
      onClick={() => onSelect?.(value)}
    >
      <span className="color-swatch-dot" aria-hidden="true" />
      {label}
    </button>
  )
}
